 "content": "def transform(grid):
    """Fill cells strictly inside complete downward-pointing diagonal triangles."""
    h = len(grid)
    if not h:
        return []
    w = len(grid[0])
    out = [row[:] for row in grid]
    # A valid outline has a colored apex on the top edge and both diagonal
    # boundary rays fully represented in the grid down to its base.
    for c, color in enumerate(grid[0]):
        if not color:
            continue
        depth = min(c, w - 1 - c, h - 1)
        # Require the triangle's sides to remain visible through the rows
        # being filled; truncated outlines do not enclose an interior.
        for r in range(1, depth + 1):
            left, right = c - r, c + r
            for x in range(left + 1, right):
                if out[r][x] == 0:
                    out[r][x] = 2
    return out
